export const INSURANCE_CATALOGUE_VERSION = 'za-non-life-2026.07.1' as const;

export type InsuranceClientSegment = 'domestic' | 'commercial';

export type InsuranceIndustryProfileKey =
  | 'agriculture_farming'
  | 'transport_logistics'
  | 'construction_engineering'
  | 'industrial_manufacturing'
  | 'mining_utilities'
  | 'retail_wholesale'
  | 'hospitality_tourism_leisure_events'
  | 'professional_services'
  | 'real_estate_sectional_title'
  | 'healthcare'
  | 'motor_trade'
  | 'marine_operations'
  | 'aviation'
  | 'rail'
  | 'renewable_energy'
  | 'other_specialist_referral';

export type InsuranceRegulatoryClassKey =
  | 'motor'
  | 'property'
  | 'agriculture'
  | 'engineering'
  | 'marine'
  | 'aviation'
  | 'transport'
  | 'rail'
  | 'legal_expense'
  | 'liability'
  | 'credit_guarantee'
  | 'accident_health'
  | 'travel'
  | 'miscellaneous'
  | 'reinsurance';

export type InsuranceRegulatoryMapping = {
  classKey: InsuranceRegulatoryClassKey;
  subclass: string;
};

export type InsuranceCoverElementDefinition = {
  key: string;
  label: string;
  summary: string;
};

export type InsuranceUnderwritingQuestion = {
  key: string;
  question: string;
  requiredDataFields: string[];
};

export type InsuranceCoverDefinition = {
  key: string;
  label: string;
  aliases: string[];
  familyKey: string;
  catalogueVersion: typeof INSURANCE_CATALOGUE_VERSION;
  eligibleClientSegments: InsuranceClientSegment[];
  relevantIndustryProfiles: InsuranceIndustryProfileKey[];
  regulatoryMappings: InsuranceRegulatoryMapping[];
  applicableRiskObjectTypes: string[];
  applicableExposureTypes: string[];
  purpose: string;
  insuredInterestSummary: string;
  triggerSummary: string;
  physicalDamageNormallyRequired: boolean | 'varies';
  coreCoverElements: InsuranceCoverElementDefinition[];
  commonExtensions: InsuranceCoverElementDefinition[];
  limitationsAndConditions: string[];
  underwritingQuestions: InsuranceUnderwritingQuestion[];
  requiredDataFields: string[];
  valuationGuidance: string[];
  limitGuidance: string[];
  excessGuidance: string[];
  evidenceRequirements: string[];
  dependencies: string[];
  overlaps: string[];
  moreSpecificCoverRelationships: string[];
  sourceReferences: string[];
  claimsLens: string;
  specialistReferral: boolean;
};

