export const INSURANCE_REGULATORY_CLASSES: ReadonlyArray<{ key: InsuranceRegulatoryClassKey; label: string }> = [
  ['motor', 'Motor'], ['property', 'Property'], ['agriculture', 'Agriculture'], ['engineering', 'Engineering'],
  ['marine', 'Marine'], ['aviation', 'Aviation'], ['transport', 'Transport'], ['rail', 'Rail'],
  ['legal_expense', 'Legal Expense'], ['liability', 'Liability'], ['credit_guarantee', 'Credit and Guarantee'],
  ['accident_health', 'Accident and Health'], ['travel', 'Travel'], ['miscellaneous', 'Miscellaneous'],
  ['reinsurance', 'Reinsurance (classification metadata only)'],
].map(([key, label]) => ({ key: key as InsuranceRegulatoryClassKey, label }));

type CoverSeed = {
  key: string;
  label: string;
  aliases: string[];
  familyKey: string;
  segments: InsuranceClientSegment[];
  industries?: InsuranceIndustryProfileKey[];
  regulatory: Array<[InsuranceRegulatoryClassKey, string]>;
  riskObjects: string[];
  exposures: string[];
  purpose: string;
  interest: string;
  trigger: string;
  physicalDamage: boolean | 'varies';
  core: string[];
  extensions: string[];
  limitations: string[];
  questions: string[];
  dataFields: string[];
  valuation: string;
  evidence: string;
  dependencies?: string[];
  overlaps?: string[];
  moreSpecific?: string[];
  source: string;
  claims: string;
  specialist?: boolean;
};

const allCommercialIndustries = INSURANCE_INDUSTRY_PROFILES.map((profile) => profile.key);

function element(label: string, index: number): InsuranceCoverElementDefinition {
  return {
    key: `${label.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '') || 'element'}_${index + 1}`,
    label,
    summary: label,
  };
}

function defineCover(seed: CoverSeed): InsuranceCoverDefinition {
  return {
    key: seed.key,
    label: seed.label,
    aliases: seed.aliases,
    familyKey: seed.familyKey,
    catalogueVersion: INSURANCE_CATALOGUE_VERSION,
    eligibleClientSegments: seed.segments,
    relevantIndustryProfiles: seed.industries ?? (seed.segments.includes('commercial') ? allCommercialIndustries : []),
    regulatoryMappings: seed.regulatory.map(([classKey, subclass]) => ({ classKey, subclass })),
    applicableRiskObjectTypes: seed.riskObjects,
    applicableExposureTypes: seed.exposures,
    purpose: seed.purpose,
    insuredInterestSummary: seed.interest,
    triggerSummary: seed.trigger,
    physicalDamageNormallyRequired: seed.physicalDamage,
    coreCoverElements: seed.core.map(element),
    commonExtensions: seed.extensions.map(element),
    limitationsAndConditions: seed.limitations,
    underwritingQuestions: seed.questions.map((question, index) => ({
      key: `${seed.key}_question_${index + 1}`,
      question,
      requiredDataFields: seed.dataFields,
    })),
    requiredDataFields: seed.dataFields,
    valuationGuidance: [seed.valuation],
    limitGuidance: ['Record the contractual limit type, amount, currency, VAT basis, aggregation and effective dates from the schedule or wording.'],
    excessGuidance: ['Record every applicable basic, additional, percentage and time excess separately; do not collapse them into one free-text amount.'],
    evidenceRequirements: [seed.evidence, 'Current policy schedule, applicable wording edition and endorsements where current cover is recorded.'],
    dependencies: seed.dependencies ?? [],
    overlaps: seed.overlaps ?? [],
    moreSpecificCoverRelationships: seed.moreSpecific ?? [],
    sourceReferences: [`Aim4price handbook ${seed.source}`],
    claimsLens: seed.claims,
    specialistReferral: Boolean(seed.specialist),
  };
}

