export const INSURANCE_COVER_CATALOGUE: ReadonlyArray<InsuranceCoverDefinition> = coverSeeds.map(defineCover);

export const INSURANCE_COVER_BY_KEY: Readonly<Record<string, InsuranceCoverDefinition>> = Object.freeze(
  Object.fromEntries(INSURANCE_COVER_CATALOGUE.map((cover) => [cover.key, cover])),
);

export function insuranceCoverDefinition(key: string): InsuranceCoverDefinition | null {
  return INSURANCE_COVER_BY_KEY[key] ?? null;
}

export function searchInsuranceCoverCatalogue(input: {
  query?: string;
  segment?: InsuranceClientSegment;
  industry?: InsuranceIndustryProfileKey;
  regulatoryClass?: InsuranceRegulatoryClassKey;
  familyKey?: string;
}): InsuranceCoverDefinition[] {
  const query = (input.query ?? '').trim().toLowerCase();
  return INSURANCE_COVER_CATALOGUE.filter((cover) => {
    if (input.segment && !cover.eligibleClientSegments.includes(input.segment)) return false;
    if (input.industry && !cover.relevantIndustryProfiles.includes(input.industry)) return false;
    if (input.regulatoryClass && !cover.regulatoryMappings.some((mapping) => mapping.classKey === input.regulatoryClass)) return false;
    if (input.familyKey && cover.familyKey !== input.familyKey) return false;
    if (!query) return true;
    return [cover.label, cover.key, cover.familyKey, ...cover.aliases, cover.purpose]
      .join(' ')
      .toLowerCase()
      .includes(query);
  });
}
